fn beats(ys: List[Int], xs: List[Int], v: Int) -> Bool
  requires (len(xs) >= 0)
  ensures (result == (forall y in ys: ((y == v) or (count(xs, y) < count(xs, v)))))
  effects pure
  example (beats([1, 2, 2], [1, 2, 2], 2) == true)
  example (beats([1, 2], [1, 2], 2) == false)
{
  match ys { [] => true [h, ..t] => (((h == v) or (cnt(xs, h) < cnt(xs, v))) and beats(t, xs, v)) }
}

fn cnt(xs: List[Int], x: Int) -> Int
  requires (len(xs) >= 0)
  ensures (result == count(xs, x))
  effects pure
  example (cnt([1, 2, 2], 2) == 2)
  example (cnt([], 5) == 0)
{
  match xs { [] => 0 [h, ..t] => if (h == x) then (1 + cnt(t, x)) else cnt(t, x) }
}

fn count_occurrences(xs: List[Int], x: Int) -> Int
  requires (len(xs) >= 0)
  ensures (result == count(xs, x))
  effects pure
  example (count_occurrences([1, 2, 2, 3], 2) == 2)
  example (count_occurrences([], 1) == 0)
  example (count_occurrences([1, 2, 2, 2], 2) == 3)
{
  match xs { [] => 0 [h, ..t] => if (h == x) then (1 + count_occurrences(t, x)) else count_occurrences(t, x) }
}

fn is_mode(xs: List[Int], r: Option[Int]) -> Bool
  requires (len(xs) >= 0)
  ensures (result == (((len(xs) == 0) and (r == None)) or (exists v in xs: ((r == Some(v)) and (forall y in xs: ((y == v) or (count(xs, y) < count(xs, v))))))))
  effects pure
  example (is_mode([1, 2, 2, 3], Some(2)) == true)
  example (is_mode([1, 2, 2, 3], Some(1)) == false)
  example (is_mode([], None) == true)
  example (is_mode([], Some(1)) == false)
  example (is_mode([1], None) == false)
{
  match r { None => match xs { [] => true _ => false } Some(v) => ((cnt(xs, v) > 0) and beats(xs, xs, v)) }
}

fn find_max_by_count(xs: List[Int], current_max: Int, remaining: List[Int]) -> Int
  requires (contains(xs, current_max) and (forall r in remaining: (contains(xs, r) and (exists x in xs: forall y in xs: ((y == x) or (count(xs, y) < count(xs, x)))))))
  ensures (contains(xs, result) and (forall y in xs: ((y == result) or (count(xs, y) < count(xs, result)))))
  effects pure
  example (find_max_by_count([1, 2, 2, 3], 1, [1, 2, 2, 3]) == 2)
  example (find_max_by_count([5, 5, 5, 1, 1], 5, [5, 5, 5, 1, 1]) == 5)
{
  match remaining { [] => current_max [h, ..t] => if (count_occurrences(xs, h) > count_occurrences(xs, current_max)) then find_max_by_count(xs, h, t) else find_max_by_count(xs, current_max, t) }
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires ((len(xs) == 0) or (exists x in xs: forall y in xs: ((y == x) or (count(xs, y) < count(xs, x)))))
  ensures is_mode(xs, result)
  effects pure
  example (most_frequent([1, 2, 2, 3]) == Some(2))
  example (most_frequent([]) == None)
  example (most_frequent([5]) == Some(5))
  example (most_frequent([3, 1, 3, 1, 3]) == Some(3))
{
  match xs { [] => None [h, ..t] => Some(find_max_by_count(xs, h, xs)) }
}

fn remove_first(xs: List[Int], val: Int) -> List[Int]
  requires contains(xs, val)
  ensures (len(result) == (len(xs) - 1))
  effects pure
  example (remove_first([3, 9, 1], 9) == [3, 1])
  example (remove_first([5, 2], 5) == [2])
  example (remove_first([1, 2, 3], 1) == [2, 3])
{
  match xs { [] => [] [h, ..t] => if (h == val) then t else ([h] ++ remove_first(t, val)) }
}

fn find_second_after_removing_max(xs: List[Int], max_elem: Int) -> Option[Int]
  requires (contains(xs, max_elem) and (forall x in xs: ((x <= max_elem) and (len(xs) >= 2))))
  ensures match result { None => not (exists x in xs: (x < max_elem)) Some(v) => ((contains(xs, v) and (v < max_elem)) and (forall x in xs: ((x == max_elem) or (x <= v)))) }
  effects pure
  example (find_second_after_removing_max([3, 9, 1], 9) == Some(3))
  example (find_second_after_removing_max([1, 2], 2) == Some(1))
{
  match remove_first(xs, max_elem) { [] => None rest => Some(find_max(rest)) }
}

fn find_max(xs: List[Int]) -> Int
  requires (len(xs) > 0)
  ensures (contains(xs, result) and (forall x in xs: (x <= result)))
  effects pure
  example (find_max([3, 9, 1]) == 9)
  example (find_max([5]) == 5)
  example (find_max([1, 2, 3, 4, 5]) == 5)
{
  match xs { [h, ..t] => match t { [] => h _ => if (h > find_max(t)) then h else find_max(t) } [] => 0 }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures match result { None => (len(xs) < 2) Some(v) => (contains(xs, v) and (exists y in xs: ((y > v) and (forall z in xs: ((z <= v) or (z == y)))))) }
  effects pure
  example (second_largest([3, 9, 1]) == Some(3))
  example (second_largest([4]) == None)
  example (second_largest([]) == None)
  example (second_largest([1, 2]) == Some(1))
  example (second_largest([5, 8, 6, 7]) == Some(7))
{
  match xs { [] => None [_, ..t] => match t { [] => None _ => find_second_after_removing_max(xs, find_max(xs)) } }
}
